import { createStore, StoreObj, vueReactive } from '@cloudsop/horizon';
import {
  FilterAction,
  FilterComputed,
  FilterState,
  StoreDefinition,
  StoreSetup,
  Store,
  AnyFunction,
  ActionType,
  StoreToRefsReturn,
} from './types';

const { ref, reactive, isRef, toRef, isReactive, isReadonly, computed } = vueReactive;

const storeMap = new Map<string, any>();

export function defineStore<
  Id extends string,
  S extends Record<string, unknown>,
  A extends Record<string, AnyFunction>,
  C extends Record<string, AnyFunction>,
>(definition: StoreDefinition<Id, S, A, C>): (pinia?: any) => Store<S, A, C>;

export function defineStore<
  Id extends string,
  S extends Record<string, unknown>,
  A extends Record<string, AnyFunction>,
  C extends Record<string, AnyFunction>,
>(id: Id, definition: Omit<StoreDefinition<Id, S, A, C>, 'id'>): (pinia?: any) => Store<S, A, C>;

export function defineStore<Id extends string, SS extends Record<any, unknown>>(
  id: Id,
  setup: StoreSetup<SS>
): (pinia?: any) => Store<FilterState<SS>, FilterAction<SS>, FilterComputed<SS>>;

export function defineStore(idOrDef: any, setupOrDef?: any) {
  let id: string;
  let definition: StoreDefinition | StoreSetup;
  let isSetup = false;

  if (typeof idOrDef === 'string') {
    isSetup = typeof setupOrDef === 'function';
    id = idOrDef;
    definition = setupOrDef;
  } else {
    id = idOrDef.id;
    definition = idOrDef;
  }

  if (isSetup) {
    return defineSetupStore(id, definition as StoreSetup);
  } else {
    return defineOptionsStore(id, definition as StoreDefinition);
  }
}

/**
 * createStore实现中会给actions增加第一个参数store，pinia不需要，所以需要去掉
 * @param actions
 */
function enhanceActions(
  actions?: ActionType<Record<string, AnyFunction>, Record<string, unknown>, Record<string, AnyFunction>>
) {
  if (!actions) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(actions).map(([key, value]) => {
      return [
        key,
        function (this: StoreObj, state: Record<string, unknown>, ...args: any[]) {
          return value.bind(this)(...args);
        },
      ];
    })
  );
}

function defineOptionsStore(id: string, definition: StoreDefinition) {
  const state = definition.state ? definition.state() : {};
  const computedGetters = definition.getters || {};
  const actions = enhanceActions(definition.actions) || {};

  return () => {
    if (storeMap.has(id)) {
      return storeMap.get(id)!();
    }

    const useStore = createStore({
      id,
      state,
      actions,
      computed: computedGetters,
    });

    storeMap.set(id, useStore);

    return useStore();
  };
}

function defineSetupStore<SS extends Record<string, unknown>>(id: string, storeSetup: StoreSetup<SS>) {
  return () => {
    const data = storeSetup();
    if (!data) {
      return {};
    }

    if (storeMap.has(id)) {
      return storeMap.get(id)!();
    }

    const state: Record<string, unknown> = {};
    const actions: Record<string, AnyFunction> = {};
    const getters: Record<string, AnyFunction> = {};
    for (const key in data) {
      const prop = data[key];

      if ((isRef(prop) && !isReadonly(prop)) || isReactive(prop)) {
        // state
        state[key] = prop;
      } else if (typeof prop === 'function') {
        // action
        actions[key] = prop as AnyFunction;
      } else if (isRef(prop) && isReadonly(prop)) {
        // getters
        getters[key] = (prop as any).getter as AnyFunction;
      }
    }

    const useStore = createStore({
      id,
      state,
      computed: getters,
      actions: enhanceActions(actions),
    });

    storeMap.set(id, useStore);

    return useStore();
  };
}

export function mapStores<
  S extends Record<string, unknown>,
  A extends Record<string, AnyFunction>,
  C extends Record<string, AnyFunction>,
>(...stores: (() => Store<S, A, C>)[]): { [key: string]: () => Store<S, A, C> } {
  const result: { [key: string]: () => Store<S, A, C> } = {};

  stores.forEach((store: () => Store<S, A, C>) => {
    const expandedStore = store();
    result[`${expandedStore.id}Store`] = () => expandedStore;
  });

  return result;
}

export function storeToRefs<
  S extends Record<string, unknown>,
  A extends Record<string, AnyFunction>,
  C extends Record<string, AnyFunction>,
>(store: Store<S, A, C>): StoreToRefsReturn<S, C> {
  const stateRefs = {} as Record<string, any>;

  for (const key in store.$s) {
    Object.defineProperty(stateRefs, key, {
      get() {
        return ref(store.$s[key]);
      },
      set(newVal) {
        store.$s[key] = newVal;
      },
      enumerable: true,
    });
  }

  Object.entries(store.$config.computed || {}).map(([key, getterFn]) => {
    return (stateRefs[key] = computed(() => {
      // 处理带 state 参数的 getter
      if (getterFn.length > 0) {
        return (getterFn as any)(store.$s);
      }
      // 处理无参 getter
      return (getterFn as any).call(store);
    }));
  });

  return stateRefs as StoreToRefsReturn<S, C>;
}

/**
 * Maps state properties from a store to an object of computed properties.
 * This helper is similar to Pinia's `mapState`.
 *
 * @param storeUseFn - The store's use-function (e.g., `useCounterStore`).
 * @param keys - An array of state keys (strings) or an object mapping new names to state keys.
 * @returns An object where keys are the state names (or aliases) and values are `vueReactive.computed` results.
 */
export function mapState<
  S extends Record<string, unknown>,
  A extends Record<string, AnyFunction>,
  C extends Record<string, AnyFunction>,
  MappedKeys extends string | number | symbol,
>(
  storeUseFn: () => Store<S, A, C>,
  keys: (keyof S)[] | { [key in MappedKeys]: keyof S }
): { [key in MappedKeys | (keyof S & string)]: ReturnType<typeof computed> } {
  const store = storeUseFn();
  const mapped: { [key: string]: ReturnType<typeof computed> } = {};

  if (Array.isArray(keys)) {
    // If keys is an array of strings
    keys.forEach(key => {
      if (key in store.$s) {
        mapped[key as string] = computed(() => store.$s[key as keyof S]);
      } else {
        console.warn(`[mapState] State property '${String(key)}' not found in store '${store.id}'.`);
      }
    });
  } else {
    // If keys is an object mapping aliases to original keys
    for (const alias in keys) {
      const originalKey = keys[alias];
      if (originalKey in store.$s) {
        mapped[alias] = computed(() => store.$s[originalKey as keyof S]);
      } else if (typeof originalKey === 'function') {
        // 函数必须包装成 computed，才能响应式更新
        mapped[alias] = computed(() => originalKey(store.$s));
      } else {
        console.warn(
          `[mapState] State property '${String(originalKey)}' (aliased as '${alias}') not found in store '${store.id}'.`
        );
      }
    }
  }

  return mapped as { [key in MappedKeys | (keyof S & string)]: ReturnType<typeof computed> };
}

/**
 * Maps action properties from a store to an object of functions.
 * This helper is similar to Pinia's `mapActions`.
 *
 * @param storeUseFn - The store's use-function (e.g., `useCounterStore`).
 * @param keys - An array of action keys (strings) or an object mapping new names to action keys.
 * @returns An object where keys are the action names (or aliases) and values are functions that
 * execute the corresponding action on the store instance.
 */
export function mapActions<
  S extends Record<string, unknown>,
  A extends Record<string, AnyFunction>,
  C extends Record<string, AnyFunction>,
  MappedKeys extends string | number | symbol,
>(
  storeUseFn: () => Store<S, A, C>,
  keys: (keyof A)[] | { [key in MappedKeys]: keyof A }
): { [key in MappedKeys | (keyof A & string)]: AnyFunction } {
  const store = storeUseFn();
  const mapped: { [key: string]: AnyFunction } = {};

  if (Array.isArray(keys)) {
    // If keys is an array of strings
    keys.forEach(key => {
      if (key in store.$config.actions) {
        // Bind the action to the store instance
        mapped[key as string] = (...args) => {
          store.$config.actions[key as keyof A].call(store, store.$state, ...args);
        };
      } else {
        console.warn(`[mapActions] Action '${String(key)}' not found in store '${store.id}'.`);
      }
    });
  } else {
    // If keys is an object mapping aliases to original keys
    for (const alias in keys) {
      const originalKey = keys[alias];
      if (originalKey in store.$config.actions) {
        // Bind the action to the store instance
        mapped[alias] = (...args) => {
          store.$config.actions[originalKey as keyof A].call(store, store.$state, ...args);
        };
      } else {
        console.warn(
          `[mapActions] Action '${String(originalKey)}' (aliased as '${alias}') not found in store '${store.id}'.`
        );
      }
    }
  }

  return mapped as { [key in MappedKeys | (keyof A & string)]: AnyFunction };
}

export function mapGetters<
  S extends Record<string, unknown>,
  A extends Record<string, AnyFunction>,
  C extends Record<string, AnyFunction>,
  MappedKeys extends string | number | symbol,
>(
  storeUseFn: () => Store<S, A, C>,
  keys: (keyof C)[] | { [key in MappedKeys]: keyof C }
): { [key in MappedKeys | (keyof C & string)]: ReturnType<typeof computed> } {
  const store = storeUseFn();
  const mapped: { [key: string]: ReturnType<typeof computed> } = {};

  if (Array.isArray(keys)) {
    keys.forEach(key => {
      const getterKey = key as keyof C;
      if (store.$config.computed && getterKey in store.$config.computed) {
        mapped[getterKey as string] = computed(() => (store as any)[getterKey]);
      } else {
        console.warn(`[mapGetters] Getter '${String(key)}' not found in store '${store.id}'.`);
      }
    });
  } else {
    for (const alias in keys) {
      const originalKey = keys[alias];
      if (store.$config.computed && originalKey in store.$config.computed) {
        mapped[alias] = computed(() => (store as any)[originalKey]);
      } else {
        console.warn(
          `[mapGetters] Getter '${String(originalKey)}' (aliased as '${alias}') not found in store '${store.id}'.`
        );
      }
    }
  }

  return mapped as { [key in MappedKeys | (keyof C & string)]: ReturnType<typeof computed> };
}

export function mapWritableState<
  S extends Record<string, unknown>,
  A extends Record<string, AnyFunction>,
  C extends Record<string, AnyFunction>,
  MappedKeys extends string | number | symbol,
>(
  storeUseFn: () => Store<S, A, C>,
  keys: (keyof S)[] | { [key in MappedKeys]: keyof S }
): { [key in MappedKeys | (keyof S & string)]: { value: any } } {
  const store = storeUseFn();
  const mapped: { [key: string]: { value: any } } = {};

  const createWritableRef = (stateKey: keyof S) => {
    return {
      get value() {
        return store.$s[stateKey];
      },
      set value(newVal) {
        store.$s[stateKey] = newVal;
      },
    };
  };

  if (Array.isArray(keys)) {
    keys.forEach(key => {
      if (key in store.$s) {
        mapped[key as string] = createWritableRef(key);
      } else {
        console.warn(`[mapWritableState] State property '${String(key)}' not found in store '${store.id}'.`);
      }
    });
  } else {
    for (const alias in keys) {
      const originalKey = keys[alias];
      if (originalKey in store.$s) {
        mapped[alias] = createWritableRef(originalKey as keyof S);
      } else {
        console.warn(
          `[mapWritableState] State property '${String(originalKey)}' (aliased as '${alias}') not found in store '${store.id}'.`
        );
      }
    }
  }

  return mapped as { [key in MappedKeys | (keyof S & string)]: { value: any } };
}

export function createPinia() {
  console.warn(
    `The pinia-adapter in Horizon does not support the createPinia interface. Please modify your code accordingly.`
  );

  const result = {
    install: (app: any) => {},
    use: (plugin: any) => result,
    state: {},
  };

  return result;
}
